const dialog=document.querySelector('#detail'),content=document.querySelector('#detail-content');const articles=[['일상의 풍경에서 새로운 이야기를 찾다','바닷가를 달리는 열차 한 대에서 이야기를 시작했습니다. 무엇이 보이는지 관찰하고, 어떤 감정이 떠오르는지 적어 보았습니다.\n\nAI에는 장면의 색감과 배경, 독자에게 전하고 싶은 감정을 구체적으로 설명했습니다. 만들어진 초안에서 과장된 표현을 덜어내고, 관찰한 사실과 상상을 구분하며 문장을 다듬었습니다.\n\n이번 연습을 통해 AI가 제안하는 이야기에도 글쓴이의 선택과 검토가 필요하다는 점을 배웠습니다.'],['한 장의 사진이 기사가 되기까지','사진에서 눈에 띄는 사물, 빛, 배경을 먼저 기록했습니다. 이 관찰을 바탕으로 주제를 정하고 제목과 개요를 구성했습니다.\n\n사진만으로 알 수 없는 장소의 역사나 사람들의 사연은 사실처럼 쓰지 않았습니다. 확인이 필요한 정보는 별도로 표시하는 것이 이번 글쓰기 연습의 원칙입니다.'],['좋은 답변은 좋은 질문에서 시작된다','역할, 목적, 독자, 분량을 정해 질문하니 결과를 비교하기가 쉬워졌습니다.\n\n첫 답변을 그대로 채택하기보다 모호한 부분에 다시 질문하고, 필요한 예시를 요청했습니다. 질문과 수정 내용을 함께 보관하면 다음 작업에도 유용한 기록이 됩니다.'],['기술에 나만의 시선을 더하는 법','같은 도구를 사용해도 무엇을 관찰하고 선택하는지에 따라 결과는 달라집니다.\n\n이번 교육에서는 결과물을 많이 만드는 것보다 선택한 이유를 설명하는 데 집중했습니다. 앞으로 각 작품에 기획 의도와 수정 과정을 함께 남기려고 합니다.']];document.querySelectorAll('[data-article]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();let item=articles[Number(a.dataset.article)];content.replaceChildren();const h=document.createElement('h2'),p=document.createElement('p'),meta=document.createElement('p');h.textContent=item[0];p.textContent=item[1];meta.textContent='교육용 임시 기사 · 실제 취재 보도가 아닌 글쓰기 예시입니다.';meta.className='meta';content.append(h,meta,p);dialog.showModal()}));document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{content.replaceChildren();const img=document.createElement('img'),h=document.createElement('h2');img.src=b.dataset.image;img.alt=b.dataset.title;h.textContent=b.dataset.title;content.append(img,h);dialog.showModal()}));document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
